/**
 * Static pages that live in public/ as finished HTML (not React routes), such as the monthly
 * Pulso Inocuidad PR report in public/pulso/ (generated by stratum-crm/pulso, `pulso build`).
 *
 * They are not prerendered, but they are public pages: the sitemap, llms.txt and the IndexNow
 * manifest list every index.html found under these folders, so a new edition is picked up on the
 * next build without touching code. A page with a noindex robots meta is left out.
 */
import * as fs from 'fs';
import * as path from 'path';

/** Folders under public/ that hold static pages. */
const STATIC_DIRS = ['pulso'];

export interface StaticPage {
  /** URL path with a trailing slash, e.g. /pulso/2026-11/frescos/ */
  path: string;
  title: string;
  description: string;
  /** Absolute path of the index.html file */
  file: string;
  /** The section index (e.g. /pulso/) rather than an edition page */
  isIndex: boolean;
}

const decode = (s: string) =>
  s.replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');

function walk(dir: string, out: string[]): void {
  if (!fs.existsSync(dir)) return;
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) walk(full, out);
    else if (entry.name === 'index.html') out.push(full);
  }
}

export function staticPages(publicDir = path.join(process.cwd(), 'public')): StaticPage[] {
  const files: string[] = [];
  for (const d of STATIC_DIRS) walk(path.join(publicDir, d), files);
  return files
    .map((file) => {
      const html = fs.readFileSync(file, 'utf8');
      const rel = path.relative(publicDir, path.dirname(file)).split(path.sep).join('/');
      const robots = html.match(/<meta\s+name="robots"\s+content="([^"]*)"/i)?.[1] ?? '';
      return {
        path: `/${rel}/`,
        title: decode(html.match(/<title>([^<]*)<\/title>/i)?.[1]?.trim() ?? ''),
        description: decode(html.match(/<meta\s+name="description"\s+content="([^"]*)"/i)?.[1] ?? ''),
        file,
        isIndex: STATIC_DIRS.includes(rel),
        noindex: /noindex/i.test(robots),
      };
    })
    .filter((p) => !p.noindex && p.title)
    .map(({ noindex: _n, ...p }) => p)
    .sort((a, b) => (a.isIndex === b.isIndex ? b.path.localeCompare(a.path) : a.isIndex ? -1 : 1));
}
